from pathlib import Path

p = Path('sethiquant.html')
s = p.read_text(encoding='utf-8')

# 1. Keep derivatives chart aligned with Phase 1/2A chart sizing.
old_css = '''            #market-risk-lab #model-chart,\n            #market-risk-lab #pnl-chart,\n            #market-risk-lab #corr-chart,\n            #market-risk-lab #risk-contribution-chart { height: 393px !important; }'''
new_css = '''            #market-risk-lab #model-chart,\n            #market-risk-lab #pnl-chart,\n            #market-risk-lab #corr-chart,\n            #market-risk-lab #risk-contribution-chart,\n            #market-risk-lab #derivatives-chart { height: 393px !important; }'''
if old_css not in s:
    raise SystemExit('MRL chart CSS marker not found')
s = s.replace(old_css, new_css, 1)

# 2. Add compact options-overlay launcher without expanding the analytics canvas.
old_positions = '''                            <div id="positions" class="space-y-1.5"></div>\n                        </div>\n                        <button type="submit" id="run-btn"'''
new_positions = '''                            <div id="positions" class="space-y-1.5"></div>\n                        </div>\n                        <button type="button" onclick="openOptionsOverlay()" class="w-full flex items-center justify-between px-3 py-2 rounded-lg border border-violet-200 bg-violet-50/60 hover:bg-violet-50 transition text-xs font-black text-violet-700">\n                            <span>Options Overlay</span><span id="option-count-badge" class="bg-white border border-violet-200 rounded-full px-2 py-0.5 text-[10px]">0 positions</span>\n                        </button>\n                        <button type="submit" id="run-btn"'''
if old_positions not in s:
    raise SystemExit('Positions launcher marker not found')
s = s.replace(old_positions, new_positions, 1)

# 3. Add Greeks tab and view to the existing risk-detail card.
old_tabs = '''                                    <button id="risk-tab-attribution" type="button" onclick="showRiskDetail('attribution')" class="px-2.5 py-1.5 rounded-md bg-white text-blue-700 shadow-sm">Contribution</button>\n                                    <button id="risk-tab-correlation" type="button" onclick="showRiskDetail('correlation')" class="px-2.5 py-1.5 rounded-md text-gray-500">Correlation</button>'''
new_tabs = '''                                    <button id="risk-tab-attribution" type="button" onclick="showRiskDetail('attribution')" class="px-2 py-1.5 rounded-md bg-white text-blue-700 shadow-sm">Contribution</button>\n                                    <button id="risk-tab-greeks" type="button" onclick="showRiskDetail('greeks')" class="px-2 py-1.5 rounded-md text-gray-500">Greeks</button>\n                                    <button id="risk-tab-correlation" type="button" onclick="showRiskDetail('correlation')" class="px-2 py-1.5 rounded-md text-gray-500">Correlation</button>'''
if old_tabs not in s:
    raise SystemExit('Risk tabs marker not found')
s = s.replace(old_tabs, new_tabs, 1)

old_views = '''                            <div id="risk-attribution-view"><div id="risk-contribution-chart" style="height:255px"></div></div>\n                            <div id="correlation-view" class="hidden"><div id="corr-chart" style="height:255px"></div></div>'''
new_views = '''                            <div id="risk-attribution-view"><div id="risk-contribution-chart" style="height:255px"></div></div>\n                            <div id="derivatives-view" class="hidden"><div id="derivatives-chart" style="height:255px"></div></div>\n                            <div id="correlation-view" class="hidden"><div id="corr-chart" style="height:255px"></div></div>'''
if old_views not in s:
    raise SystemExit('Risk detail views marker not found')
s = s.replace(old_views, new_views, 1)

# 4. Insert options overlay modal before the existing options-engine modal.
modal_marker = '''    <!-- MODAL: UNIFIED OPTIONS ENGINE MASTER -->'''
modal_html = '''    <!-- MODAL: MARKET RISK LAB OPTIONS OVERLAY -->\n    <div id="modal-risk-options" class="hidden fixed inset-0 z-[220] flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm p-4">\n        <div class="bg-white rounded-2xl shadow-2xl p-6 max-w-5xl w-full relative max-h-[90vh] overflow-y-auto">\n            <button type="button" onclick="toggleModal('modal-risk-options')" class="absolute top-4 right-4 text-gray-400 hover:text-red-500 text-xl font-bold">×</button>\n            <div class="pr-10 mb-5">\n                <h3 class="text-2xl font-black text-gray-900">Options Risk Overlay</h3>\n                <p class="text-sm text-gray-500 mt-1">Add up to three European options. VaR uses a Delta–Gamma–Vega approximation with simulated spot and volatility shocks.</p>\n            </div>\n            <div class="grid grid-cols-12 gap-2 px-2 mb-2 text-[10px] font-black uppercase tracking-wider text-gray-400">\n                <span class="col-span-2">Underlying</span><span class="col-span-2">Type</span><span class="col-span-2">Strike</span><span class="col-span-2">Expiry days</span><span class="col-span-2">IV %</span><span class="col-span-2">Contracts</span>\n            </div>\n            <div id="risk-options-editor" class="space-y-2"></div>\n            <div class="flex flex-wrap items-center justify-between gap-3 mt-5 pt-4 border-t border-gray-100">\n                <div class="flex gap-2">\n                    <button type="button" onclick="addRiskOption()" class="px-4 py-2 rounded-lg bg-violet-50 text-violet-700 font-black text-sm border border-violet-200">+ Add Option</button>\n                    <button type="button" onclick="clearRiskOptions()" class="px-4 py-2 rounded-lg bg-gray-50 text-gray-500 font-bold text-sm border border-gray-200">Clear</button>\n                </div>\n                <button type="button" onclick="applyRiskOptions()" class="px-5 py-2.5 rounded-lg bg-violet-600 hover:bg-violet-700 text-white font-black text-sm shadow-sm">Apply Overlay</button>\n            </div>\n            <p class="text-[11px] text-gray-400 mt-4">Positive contracts are long; negative contracts are short. Contract multiplier is 100. The approximation also includes Black–Scholes theta over the selected VaR horizon.</p>\n        </div>\n    </div>\n\n'''
if modal_marker not in s:
    raise SystemExit('Modal insertion marker not found')
s = s.replace(modal_marker, modal_html + modal_marker, 1)

# 5. Add option state/editor helpers.
state_marker = '''        let latestRiskData = null;\n\n        function renderCorrelationDetail(data) {'''
state_replacement = '''        let latestRiskData = null;\n        let activeRiskOptions = [];\n\n        function updateOptionBadge() {\n            const badge = document.getElementById('option-count-badge');\n            if (badge) badge.innerText = `${activeRiskOptions.length} ${activeRiskOptions.length === 1 ? 'position' : 'positions'}`;\n        }\n\n        function renderRiskOptionsEditor() {\n            const editor = document.getElementById('risk-options-editor');\n            if (!activeRiskOptions.length) {\n                editor.innerHTML = `<div class="rounded-xl border border-dashed border-gray-200 p-6 text-center text-sm text-gray-400">No derivatives overlay. Add an option to stress nonlinear risk.</div>`;\n                return;\n            }\n            editor.innerHTML = activeRiskOptions.map((o, i) => `\n                <div class="grid grid-cols-12 gap-2 items-center bg-gray-50 border border-gray-200 rounded-xl p-2">\n                    <input id="ro-underlying-${i}" value="${o.underlying || ''}" placeholder="AAPL" class="col-span-2 border border-gray-200 rounded-lg px-2 py-2 uppercase font-bold bg-white">\n                    <select id="ro-type-${i}" class="col-span-2 border border-gray-200 rounded-lg px-2 py-2 font-bold bg-white"><option value="call" ${o.option_type === 'call' ? 'selected' : ''}>Call</option><option value="put" ${o.option_type === 'put' ? 'selected' : ''}>Put</option></select>\n                    <input id="ro-strike-${i}" type="number" min="0.01" step="0.01" value="${o.strike ?? ''}" placeholder="200" class="col-span-2 border border-gray-200 rounded-lg px-2 py-2 font-bold bg-white">\n                    <input id="ro-expiry-${i}" type="number" min="1" max="1095" value="${o.days_to_expiry ?? 90}" class="col-span-2 border border-gray-200 rounded-lg px-2 py-2 font-bold bg-white">\n                    <input id="ro-iv-${i}" type="number" min="1.1" max="300" step="0.1" value="${o.implied_vol_pct ?? 25}" class="col-span-2 border border-gray-200 rounded-lg px-2 py-2 font-bold bg-white">\n                    <div class="col-span-2 flex gap-1"><input id="ro-contracts-${i}" type="number" min="-1000" max="1000" value="${o.contracts ?? 1}" class="min-w-0 w-full border border-gray-200 rounded-lg px-2 py-2 font-bold bg-white"><button type="button" onclick="removeRiskOption(${i})" class="px-2 text-red-500 font-black">×</button></div>\n                </div>`).join('');\n        }\n\n        function openOptionsOverlay() {\n            renderRiskOptionsEditor();\n            toggleModal('modal-risk-options');\n        }\n\n        function addRiskOption() {\n            if (activeRiskOptions.length >= 3) { alert('Use no more than three option positions in this risk overlay.'); return; }\n            const firstTicker = document.getElementById('ticker-0')?.value?.trim().toUpperCase() || 'AAPL';\n            activeRiskOptions.push({ underlying: firstTicker, option_type: 'call', strike: '', days_to_expiry: 90, implied_vol_pct: 25, contracts: 1 });\n            renderRiskOptionsEditor();\n        }\n\n        function removeRiskOption(index) {\n            activeRiskOptions.splice(index, 1);\n            renderRiskOptionsEditor();\n            updateOptionBadge();\n        }\n\n        function clearRiskOptions() {\n            activeRiskOptions = [];\n            renderRiskOptionsEditor();\n            updateOptionBadge();\n        }\n\n        function applyRiskOptions() {\n            const next = [];\n            for (let i = 0; i < activeRiskOptions.length; i++) {\n                const underlying = document.getElementById(`ro-underlying-${i}`).value.trim().toUpperCase();\n                const strike = parseFloat(document.getElementById(`ro-strike-${i}`).value);\n                const expiry = parseInt(document.getElementById(`ro-expiry-${i}`).value);\n                const ivPct = parseFloat(document.getElementById(`ro-iv-${i}`).value);\n                const contracts = parseInt(document.getElementById(`ro-contracts-${i}`).value);\n                if (!underlying || !(strike > 0) || !(expiry > 0) || !(ivPct > 1) || !Number.isFinite(contracts) || contracts === 0) {\n                    alert('Complete every option row with a valid underlying, strike, expiry, IV and non-zero contract count.');\n                    return;\n                }\n                next.push({ underlying, option_type: document.getElementById(`ro-type-${i}`).value, strike, days_to_expiry: expiry, implied_vol_pct: ivPct, contracts });\n            }\n            activeRiskOptions = next;\n            updateOptionBadge();\n            toggleModal('modal-risk-options');\n        }\n\n        function renderCorrelationDetail(data) {'''
if state_marker not in s:
    raise SystemExit('Risk state marker not found')
s = s.replace(state_marker, state_replacement, 1)

# 6. Replace the two-view toggle function with three-view logic.
start = s.find('        function showRiskDetail(view) {')
end = s.find('        let activePositions =', start)
if start == -1 or end == -1:
    raise SystemExit('showRiskDetail function boundaries not found')
new_toggle = '''        function showRiskDetail(view) {\n            const views = { attribution: document.getElementById('risk-attribution-view'), greeks: document.getElementById('derivatives-view'), correlation: document.getElementById('correlation-view') };\n            const tabs = { attribution: document.getElementById('risk-tab-attribution'), greeks: document.getElementById('risk-tab-greeks'), correlation: document.getElementById('risk-tab-correlation') };\n            const title = document.getElementById('risk-detail-title');\n            const subtitle = document.getElementById('risk-detail-subtitle');\n            Object.entries(views).forEach(([key, el]) => el.classList.toggle('hidden', key !== view));\n            Object.entries(tabs).forEach(([key, el]) => {\n                el.classList.toggle('bg-white', key === view); el.classList.toggle('text-blue-700', key === view); el.classList.toggle('shadow-sm', key === view); el.classList.toggle('text-gray-500', key !== view);\n            });\n\n            if (view === 'correlation') {\n                title.innerText = 'Asset Correlation Matrix';\n                const obs = latestRiskData?.diagnostics?.historical_observations;\n                subtitle.innerText = obs ? `${obs} observations · equity and option-underlying dependence.` : 'Dependence structure for the Monte Carlo engine.';\n                renderCorrelationDetail(latestRiskData);\n            } else if (view === 'greeks') {\n                title.innerText = 'Derivatives Risk';\n                const d = latestRiskData?.derivatives;\n                subtitle.innerText = d?.active ? `Δ £${Math.round(d.aggregate_dollar_delta).toLocaleString()} · Γ(1%) ${formatMoney(d.aggregate_gamma_pnl_1pct)} · Vega ${formatMoney(d.aggregate_vega_pnl_1vol)}/vol pt` : 'No options overlay is active.';\n                if (document.getElementById('derivatives-chart').data) Plotly.Plots.resize('derivatives-chart');\n            } else {\n                title.innerText = 'Risk Contribution';\n                const a = latestRiskData?.attribution;\n                const overlayNote = latestRiskData?.derivatives?.active ? ' · equity attribution only' : '';\n                subtitle.innerText = a ? `Parametric VaR ${formatMoney(a.portfolio_var)} · diversification ${a.diversification_pct.toFixed(1)}%${overlayNote}` : 'Run an analysis to decompose portfolio VaR.';\n                if (document.getElementById('risk-contribution-chart').data) Plotly.Plots.resize('risk-contribution-chart');\n            }\n        }\n\n'''
s = s[:start] + new_toggle + s[end:]

# 7. Send the options overlay to the backend.
payload_marker = '''            const payload = {\n                positions,\n                portfolio_value:'''
payload_replacement = '''            const payload = {\n                positions,\n                options: activeRiskOptions.map(o => ({ underlying: o.underlying, option_type: o.option_type, strike: o.strike, days_to_expiry: o.days_to_expiry, implied_vol: o.implied_vol_pct / 100, contracts: o.contracts, multiplier: 100 })),\n                portfolio_value:'''
if payload_marker not in s:
    raise SystemExit('Risk payload marker not found')
s = s.replace(payload_marker, payload_replacement, 1)

# 8. Render standardized Greek P&L shocks and default to Greeks when an overlay is active.
old_final = '''                showRiskDetail('attribution');'''
new_final = '''                const derivatives = data.derivatives;\n                const derivativesChart = document.getElementById('derivatives-chart');\n                if (derivatives?.active && Array.isArray(derivatives.options)) {\n                    const labels = derivatives.options.map(o => `${o.underlying} ${o.option_type === 'call' ? 'C' : 'P'} ${o.strike}`);\n                    Plotly.newPlot('derivatives-chart', [\n                        { x: labels, y: derivatives.options.map(o => o.delta_pnl_1pct), name: 'Delta: +1% spot', type: 'bar', marker: { color: '#7c3aed' } },\n                        { x: labels, y: derivatives.options.map(o => o.gamma_pnl_1pct), name: 'Gamma: 1% move', type: 'bar', marker: { color: '#2563eb' } },\n                        { x: labels, y: derivatives.options.map(o => o.vega_pnl_1vol), name: 'Vega: +1 vol pt', type: 'bar', marker: { color: '#059669' } }\n                    ], {\n                        barmode: 'group', margin: { t: 10, r: 10, l: 50, b: 55 },\n                        yaxis: { title: 'P&L impact (£)', gridcolor: '#f3f4f6', zeroline: true, zerolinecolor: '#d1d5db' },\n                        legend: { orientation: 'h', y: 1.12, font: { size: 9 } },\n                        paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)'\n                    }, { displayModeBar: false, responsive: true });\n                    showRiskDetail('greeks');\n                } else {\n                    derivativesChart.innerHTML = `<div class="h-full flex items-center justify-center text-sm text-gray-400 italic text-center px-8">Add an option through Options Overlay to activate Delta, Gamma and Vega risk.</div>`;\n                    showRiskDetail('attribution');\n                }'''
if old_final not in s:
    raise SystemExit('Final risk-detail selector not found')
s = s.replace(old_final, new_final, 1)

p.write_text(s, encoding='utf-8')

required = [
    'id="modal-risk-options"', 'function openOptionsOverlay()', 'id="risk-tab-greeks"',
    'id="derivatives-chart"', 'options: activeRiskOptions.map', 'data.derivatives',
    'Delta: +1% spot', 'equity attribution only'
]
missing = [m for m in required if m not in s]
if missing:
    raise SystemExit(f'Missing derivatives UI markers: {missing}')
print('Phase 2B derivatives frontend applied.')
